"""Feature schema definition."""

from posesense.exceptions import FeatureSchemaError

# The current canonical schema version. Increment if feature definition changes.
SCHEMA_VERSION = 1

# Note: The actual ordered list of feature names is generated by the FeatureExtractor,
# but can be cached or strictly defined here if desired. We use the extractor to build it.
# To ensure single source of truth, `validate_vector` takes the vector and the expected names.

def validate_vector(vec: dict[str, float], expected_names: list[str]) -> None:
    """Validate that the feature vector exactly matches the schema.
    
    Checks length, dtype (float), and finiteness (no NaN/Inf).
    Raises FeatureSchemaError otherwise.
    """
    import math

    if len(vec) != len(expected_names):
        raise FeatureSchemaError(f"Vector length {len(vec)} does not match expected {len(expected_names)}.")
        
    for name in expected_names:
        if name not in vec:
            raise FeatureSchemaError(f"Missing required feature: {name}")
            
    for k, v in vec.items():
        if not isinstance(v, (int, float)):
            raise FeatureSchemaError(f"Feature {k} is not a float.")
        if math.isnan(v) or math.isinf(v):
            raise FeatureSchemaError(f"Feature {k} is NaN or Inf.")

# Provide an import alias for backward compatibility or ease of use
from posesense.features.extractor import FeatureExtractor
